'use strict';
// A campanha original mantém as quatro primeiras etapas e seus IDs de progresso.
// As seis próximas formam um pequeno sistema escolar progressivo.
MISSIONS.find(m=>m.id==='campus').steps.push(
  arenaStep('Média da turma','A coordenação recebeu três notas e quer um número simples para acompanhar a turma.','Percorra {7, 8, 9} com for, calcule a média inteira e imprima Media: 8.',missionWrap('    int[] notas = {7, 8, 9};\n    int soma = 0;\n    // Percorra as notas e calcule a média.'),'Media: 8',/\bfor\s*\([\s\S]*\bnotas\.length\b/,['Some as notas em um laço.','Divida a soma por notas.length.','Imprima "Media: " + soma / notas.length.'],'A média distribui os pontos igualmente entre os alunos.'),
  arenaStep('Presença sem repetição','Uma mesma aluna foi marcada duas vezes na lista de presença.','Use LinkedHashSet para eliminar duplicatas de Ana, Bia, Ana, Caio e imprima cada nome na ordem de chegada.',`import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    String[] nomes = {"Ana", "Bia", "Ana", "Caio"};\n    // Monte uma presença única e percorra os nomes.\n  }\n}`,'Ana\nBia\nCaio',/\bLinkedHashSet\s*</,['LinkedHashSet mantém a ordem em que os nomes entram.','Use Set<String> presenca = new LinkedHashSet<>();','Adicione cada nome e imprima com for-each.'],'A lista de chamada dá uma cadeira por pessoa, mesmo que seu nome apareça duas vezes.'),
  arenaStep('Matrícula protegida','Uma idade negativa não pode entrar no cadastro.','Crie static void matricular(int idade) que lance IllegalArgumentException quando idade < 0. Chame com -1 em try/catch e imprima Idade inválida.',`public class Main {\n  static void matricular(int idade) {\n    // Valide a idade aqui.\n  }\n  public static void main(String[] args) {\n    try { matricular(-1); }\n    catch (IllegalArgumentException e) { System.out.println("Idade inválida"); }\n  }\n}`,'Idade inválida',/\bif\s*\([\s\S]*throw\s+new\s+IllegalArgumentException/,['Verifique idade < 0 antes de continuar.','Use throw new IllegalArgumentException("idade").','O catch já mostra a mensagem solicitada.'],'A validação é a porta da escola: dados impossíveis não passam.'),
  arenaStep('Ficha imutável','A escola quer uma ficha curta para transportar dados sem alteração.','Crie record Aluno(String nome, int turma), instancie Ana na turma 2 e imprima Ana - turma 2.',`public class Main {\n  record Aluno(String nome, int turma) {}\n  public static void main(String[] args) {\n    // Instancie Aluno e leia nome() e turma().\n  }\n}`,'Ana - turma 2',/\brecord\s+Aluno[\s\S]*\.nome\s*\([\s\S]*\.turma\s*\(/,['Crie new Aluno("Ana", 2).','Um record oferece os métodos nome() e turma().','Monte a frase com os dois valores.'],'O record é uma ficha carimbada com campos definidos.'),
  arenaStep('Quem pode receber bolsa?','A equipe quer saber quantas das notas {5, 8, 9} atendem à meta 8.','Use Arrays.stream, filter e count para imprimir Elegíveis: 2.',`import java.util.Arrays;\npublic class Main {\n  public static void main(String[] args) {\n    int[] notas = {5, 8, 9};\n    // Filtre notas >= 8 e conte.\n  }\n}`,'Elegíveis: 2',/\bArrays\.stream\s*\([\s\S]*\.filter\s*\([\s\S]*\.count\s*\(/,['Comece com Arrays.stream(notas).','Filtre com nota -> nota >= 8.','Use count() e imprima o resultado.'],'O filtro é uma peneira: só as notas que cumprem a regra seguem.'),
  arenaStep('Boletim final','Chegou a hora de combinar array, laço, decisão e média em um relatório.','Percorra {8, 9, 4}; conte notas >= 6 e imprima exatamente três linhas: Turma: 3, Aprovados: 2, Media: 7.',missionWrap('    int[] notas = {8, 9, 4};\n    int soma = 0, aprovados = 0;\n    // Percorra uma vez, some e conte.\n    // Imprima tamanho, aprovados e média inteira.'),'Turma: 3\nAprovados: 2\nMedia: 7',/\bfor\s*\([\s\S]*\bif\s*\([\s\S]*\bnotas\.length\b/,['No mesmo laço, acumule soma e teste nota >= 6.','A média inteira é soma / notas.length.','Imprima turma, aprovados e média, cada um em uma linha.'],'O relatório junta as etapas anteriores para contar a história da turma.')
);
